INSERT INTO resources (id,user_id,slug,image_path,apply_url,deadline,translations,featured,published,created_at,updated_at) VALUES ('ielts-preparation','master-password-admin','ielts-preparation','/assets/resources/british-council.webp','https://erasmus-plus.ec.europa.eu/opportunities/individuals','2026-09-20','{"en":{"title":"IELTS PREPARATION SESSION","description":"Join us this week for our educational session about IELTS, how will it help your journey abroad, how to prepare for your exam, free resources and mockup tests, and a live Q&A session to answer your questions"},"fr":{"title":"SESSION DE PRÉPARATION À L’IELTS","description":"Rejoignez-nous cette semaine pour notre session éducative sur l’IELTS : son utilité pour votre parcours à l’étranger, la préparation à l’examen, des ressources gratuites et des examens blancs, ainsi qu’une séance de questions-réponses en direct."},"ar":{"title":"جلسة تحضيرية لاختبار IELTS","description":"انضم إلينا هذا الأسبوع في جلستنا التعليمية حول IELTS، وكيف يساعدك في رحلتك إلى الخارج، وكيف تستعد للامتحان، مع موارد مجانية واختبارات تجريبية وجلسة مباشرة للإجابة عن أسئلتك."}}',1,1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO resources (id,user_id,slug,image_path,apply_url,deadline,translations,featured,published,created_at,updated_at) VALUES ('khotwa-event','master-password-admin','khotwa-event','/assets/resources/khotwa.webp','https://erasmus-plus.ec.europa.eu/opportunities/individuals','2026-01-27','{"en":{"title":"KHOTWA EVENT COMES BACK THIS SPRING","description":"Find us this week along multiple agencies, institutions, universities and educational industries with Khotwa event for 3 days starting 16 February 2027, register now and be a visitor"},"fr":{"title":"L’ÉVÉNEMENT KHOTWA REVIENT CE PRINTEMPS","description":"Retrouvez-nous cette semaine aux côtés de nombreuses agences, institutions, universités et acteurs de l’éducation lors de l’événement Khotwa, pendant 3 jours à partir du 16 février 2027. Inscrivez-vous dès maintenant pour y assister."},"ar":{"title":"فعالية خطوة تعود هذا الربيع","description":"تجدوننا هذا الأسبوع إلى جانب العديد من الوكالات والمؤسسات والجامعات والجهات التعليمية في فعالية خطوة لمدة 3 أيام ابتداءً من 16 فبراير 2027. سجّل الآن وكن من الزوار."}}',1,1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO resources (id,user_id,slug,image_path,apply_url,deadline,translations,featured,published,created_at,updated_at) VALUES ('csca-mock-tests','master-password-admin','csca-mock-tests',NULL,'https://erasmus-plus.ec.europa.eu/opportunities/individuals','2026-01-27','{"en":{"title":"CSCA CHINA BACHELOR EXAM MOCKUP TESTS","description":"More than 100+ CSCA exams mockups for students willing to take the exam, each sector raises the difficulty so you Can practice your real level"},"fr":{"title":"EXAMENS BLANCS CSCA POUR LA LICENCE EN CHINE","description":"Plus de 100 examens blancs CSCA pour les étudiants souhaitant passer l’examen. Chaque section augmente la difficulté pour vous permettre de vous entraîner à votre véritable niveau."},"ar":{"title":"اختبارات CSCA التجريبية للبكالوريوس في الصين","description":"أكثر من 100 اختبار CSCA تجريبي للطلاب الراغبين في اجتياز الامتحان. يرفع كل قسم مستوى الصعوبة حتى تتمكن من التدرب وفق مستواك الحقيقي."}}',0,1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
INSERT INTO resources (id,user_id,slug,image_path,apply_url,deadline,translations,featured,published,created_at,updated_at) VALUES ('venice-webinar','master-password-admin','venice-webinar',NULL,'https://erasmus-plus.ec.europa.eu/opportunities/individuals','2026-10-10','{"en":{"title":"WEBINAR BY UNIVERSITY OF VENICE, ITALY","description":"University of Venice in Italy is hosting a webinar this Friday 13 October, 2026 to show students its campus, dorm, facilities and host a live Q&A to answer international students questions."},"fr":{"title":"WEBINAIRE DE L’UNIVERSITÉ DE VENISE, ITALIE","description":"L’Université de Venise, en Italie, organise un webinaire ce vendredi 13 octobre 2026 pour présenter son campus, ses résidences et ses installations, avec une séance de questions-réponses en direct pour les étudiants internationaux."},"ar":{"title":"ندوة عبر الإنترنت من جامعة البندقية، إيطاليا","description":"تنظم جامعة البندقية في إيطاليا ندوة عبر الإنترنت يوم الجمعة 13 أكتوبر 2026 لتعريف الطلاب بالحرم الجامعي والسكن والمرافق، مع جلسة مباشرة للإجابة عن أسئلة الطلاب الدوليين."}}',0,1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
